SIFT特征提取&amp;描述子计算实现<pre><code>// sift_dispatch.cpp
// 为保障代码连贯性，移除了安全检查和性能统计代码
void SIFT_Impl::detectAndCompute(
  InputArray _image, InputArray _mask, 
  std::vector&lt;KeyPoint&gt;&amp; keypoints, OutputArray _descriptors,
  bool useProvidedKeypoints) {

  // ========== 1.预处理 ==========

  // 参数初始化：
  //   初始倍频程firstOctave，0表示原图，-1表示对原图上采样
  //   先验倍频程数actualNOctaves
  int firstOctave = -1, actualNOctaves = 0;

  // 从InputArray获取cv::Mat
  Mat image = _image.getMat(), mask = _mask.getMat();

  // 先验点处理
  if( useProvidedKeypoints ) {//(1)!
    firstOctave = 0;
    int maxOctave = INT_MIN;
    for( size_t i = 0; i &lt; keypoints.size(); i++ ) {
      int octave, layer;
      float scale;
      // 从先验点中解码octave, layer, scale
      unpackOctave(keypoints[i], octave, layer, scale);//(2)!
      firstOctave = std::min(firstOctave, octave);
      maxOctave = std::max(maxOctave, octave);
    }

    firstOctave = std::min(firstOctave, 0);
    actualNOctaves = maxOctave - firstOctave + 1;
  }

  // ========== 2.DoG金字塔构建 ==========
  // 原始图上采样，高斯模糊
  Mat base = createInitialImage(image, firstOctave &lt; 0, (float)sigma);//(3)!

  std::vector&lt;Mat&gt; gpyr;
  // 确定总倍频程数
  int nOctaves = actualNOctaves &gt; 0 ? 
    actualNOctaves : 
    cvRound(std::log((double)std::min(base.cols, base.rows)) / //(4)!
            std::log(2.) - 2) - firstOctave;

  // 构建高斯金字塔
  buildGaussianPyramid(base, gpyr, nOctaves);

  // 构建DoG金字塔
  std::vector&lt;Mat&gt; dogpyr;
  buildDoGPyramid(gpyr, dogpyr);

  // 寻找局部极值
  findScaleSpaceExtrema(gpyr, dogpyr, keypoints);
  KeyPointsFilter::removeDuplicatedSorted( keypoints );

  if(nfeatures &gt; 0)
    KeyPointsFilter::retainBest(keypoints, nfeatures);

  if(firstOctave &lt; 0)
    for( size_t i = 0; i &lt; keypoints.size(); i++ ) {
      KeyPoint&amp; kpt = keypoints[i];
      float scale = 1.f/(float)(1 &lt;&lt; -firstOctave);
      kpt.octave = (kpt.octave &amp; ~255) | ((kpt.octave + firstOctave) &amp; 255);
      kpt.pt *= scale;
      kpt.size *= scale;
    }

  if(!mask.empty())
    KeyPointsFilter::runByPixelsMask( keypoints, mask );

  if(_descriptors.needed()) {
    int dsize = descriptorSize();
    _descriptors.create((int)keypoints.size(), dsize, descriptor_type);

    Mat descriptors = _descriptors.getMat();
    calcDescriptors(gpyr, keypoints, descriptors, nOctaveLayers, firstOctave);
  }
}
</code></pre> <ol> <li>有先验点时（<code>useProvidedKeypoints == true</code>），根据先验点确定初始倍频程<code>firstOctave</code>和先验倍频程数<code>actualNOctave</code>，前者决定是否对原图上采样，后者决定本次特征提取的倍频程数。</li> <li>详见此处</li> <li>详见此处</li> <li>记图像长宽为\(w\times h\)，则倍频程数为\(\log_2(\min(w,h))-2\)，\(-2\)为防止金字塔顶层图像过小，若对原始图像上采样则再\(+1\)</li> </ol>

Example<pre><code>#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;opencv2/core.hpp&gt;
#include &lt;opencv2/imgproc.hpp&gt;
#include &lt;opencv2/imgcodecs.hpp&gt;
#include &lt;opencv2/features2d.hpp&gt;
#include &lt;opencv2/highgui.hpp&gt;

int main(int argc, char **argv) {

  if (argc &lt; 2) {
      std::cerr &lt;&lt; "Usage: " &lt;&lt; argv[0] &lt;&lt; " &lt;image_path&gt;" &lt;&lt; std::endl;
      return -1;
  }
  cv::Mat img = cv::imread(std::string(argv[1]), cv::IMREAD_GRAYSCALE);

  // 创建 SIFT Detector
  int nfeatures = 500;
  int nOctaveLayers = 3;
  double constrastThreshold = 0.04;
  double edgeThreshold = 10;
  double sigma = 1.6;
  auto sift = cv::SIFT::create(
    nfeatures, nOctaveLayers, constrastThreshold, 
    edgeThreshold, sigma
  );

  // 提取特征点，计算描述子
  std::vector&lt;cv::KeyPoint&gt; keypoints;
  cv::Mat descriptors;
  bool useProvidedKeypoints = false;
  sift-&gt;detectAndCompute(
    img, cv::noArray(), keypoints, 
    descriptors, useProvidedKeypoints
  );

  cv::Mat display;
  cv::cvtColor(img, display, cv::COLOR_GRAY2BGR);
  for (const auto &amp;kp : keypoints) {
    cv::circle(display, kp.pt, 2, cv::Scalar(0, 255, 0), -1);
  }
  cv::imshow("SIFT Keypoints", display);
  cv::waitKey(0);

  return 0;
}
</code></pre> <ol> <li> <p>D. G. Lowe, “Distinctive image features from scale-invariant keypoints,” International journal of computer vision, vol. 60, no. 2, pp. 91–110, 2004. ↩</p> </li> <li> <p>OpenCV 4.5.5 SIFT Class Reference ↩</p> </li> </ol>
